/* Client-side search over search-index.json (generated by build.py). */
(function () {
  "use strict";
  var box = document.getElementById("search-results");
  var status = document.getElementById("search-status");
  var input = document.getElementById("page-search");
  if (!box) return;

  var indexUrl = new URL(box.getAttribute("data-index"), location.href);
  var root = new URL("./", indexUrl); // the site root, wherever the site is hosted
  var query = (new URLSearchParams(location.search).get("q") || "").trim();
  input.value = query;
  if (!query) { status.textContent = "Type a word and press Enter."; return; }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function mark(text, terms) {
    var out = esc(text);
    terms.forEach(function (t) {
      if (t.length < 2) return;
      out = out.replace(new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "gi"), "<mark>$1</mark>");
    });
    return out;
  }
  function snippet(doc, terms) {
    var text = doc.x || "";
    var low = text.toLowerCase();
    for (var i = 0; i < terms.length; i++) {
      var at = low.indexOf(terms[i]);
      if (at > -1) {
        var start = Math.max(0, at - 80);
        return (start ? "…" : "") + text.slice(start, start + 220) + "…";
      }
    }
    return doc.s || text.slice(0, 200);
  }

  status.textContent = "Searching…";
  fetch(indexUrl).then(function (r) { return r.json(); }).then(function (docs) {
    var terms = query.toLowerCase().split(/\s+/).filter(Boolean);
    var hits = docs.map(function (d) {
      var title = d.t.toLowerCase(), tags = (d.k || []).join(" ").toLowerCase();
      var sum = (d.s || "").toLowerCase(), text = (d.x || "").toLowerCase();
      var score = 0;
      for (var i = 0; i < terms.length; i++) {
        var t = terms[i], s = 0;
        if (title.indexOf(t) > -1) s += 10;
        if (tags.indexOf(t) > -1) s += 6;
        if (sum.indexOf(t) > -1) s += 3;
        if (text.indexOf(t) > -1) s += 1;
        if (!s) return null; // every word must match somewhere
        score += s;
      }
      return { doc: d, score: score };
    }).filter(Boolean).sort(function (a, b) { return b.score - a.score; });

    status.textContent = hits.length
      ? hits.length + (hits.length === 1 ? " result" : " results") + " for “" + query + "”"
      : "Nothing found for “" + query + "”.";
    box.innerHTML = hits.map(function (h) {
      var d = h.doc, href = new URL(d.u, root).href;
      return '<article class="card"><div class="card-body">' +
        '<h3 class="card-title"><a href="' + esc(href) + '">' + mark(d.t, terms) + "</a></h3>" +
        (d.d ? '<p class="card-date">' + esc(d.d) + "</p>" : "") +
        '<p class="card-excerpt">' + mark(snippet(d, terms), terms) + "</p>" +
        '<a class="card-more" href="' + esc(href) + '">Read More »</a></div></article>';
    }).join("");
  }).catch(function () {
    status.textContent = "Search is unavailable right now.";
  });
})();
